import ast, os
src = open('/tmp/ref/tally/reports.py', encoding='utf-8').read()
tree = ast.parse(src)
names = []
for n in tree.body:
    if isinstance(n, (ast.FunctionDef, ast.ClassDef)): names.append(n.name)
    elif isinstance(n, ast.Assign):
        for t in n.targets:
            if isinstance(t, ast.Name): names.append(t.id)
pub = [n for n in names if not n.startswith('_') and n != '__all__']
root = '/app/tally/reports'
home = {}
for dp, _, fs in os.walk(root):
    for f in fs:
        if not f.endswith('.py') or (f == '__init__.py'): continue
        p = os.path.join(dp, f)
        t = ast.parse(open(p).read())
        mod = 'tally.reports.' + os.path.relpath(p, root)[:-3].replace('/', '.')
        for n in t.body:
            ns = []
            if isinstance(n, (ast.FunctionDef, ast.ClassDef)): ns = [n.name]
            elif isinstance(n, ast.Assign): ns = [x.id for x in n.targets if isinstance(x, ast.Name)]
            for x in ns: home.setdefault(x, []).append(mod)
bad = [n for n in names if n != '__all__' and (n not in home or len(home[n]) != 1)]
print('missing/dup', [(n, home.get(n)) for n in bad])
print('new names', [(n, m) for n, m in home.items() if n not in names])
by = {}
for n in pub: by.setdefault(home[n][0], []).append(n)
doc = src.split('"""')[1]
lines = ['"""' + doc + '"""', '', 'from __future__ import annotations', '']
order = sorted(by, key=lambda m: (not m.startswith('tally.reports.renderers'), m))
for m in order:
    rel = '.' + m[len('tally.reports.'):]
    lines.append(f'from {rel} import ' + ', '.join(by[m]))
all_node = [n for n in tree.body if isinstance(n, ast.Assign) and n.targets[0].id == '__all__'][0]
all_ = ast.literal_eval(all_node.value)
lines += ['', '__all__ = ['] + [f'    "{a}",' for a in all_] + [']']
open(root + '/__init__.py', 'w', encoding='utf-8').write('\n'.join(lines) + '\n')

