import ast, builtins, glob
for p in glob.glob('tally/reports/**/*.py', recursive=True):
    t = ast.parse(open(p).read())
    bound=set(dir(builtins)); loads={}; imported=set()
    for n in ast.walk(t):
        if isinstance(n,(ast.Import,ast.ImportFrom)):
            for a in n.names:
                nm=(a.asname or a.name).split('.')[0]; bound.add(nm); imported.add(nm)
        elif isinstance(n,(ast.FunctionDef,ast.ClassDef)): bound.add(n.name)
        elif isinstance(n,ast.arg): bound.add(n.arg)
        elif isinstance(n,ast.Name):
            if isinstance(n.ctx,ast.Load): loads.setdefault(n.id,n.lineno)
            else: bound.add(n.id)
        elif isinstance(n,ast.ExceptHandler) and n.name: bound.add(n.name)
    miss={k:v for k,v in loads.items() if k not in bound}
    # string annotations are not evaluated; ignore
    unused=[i for i in imported if i not in loads and i!='annotations' and not p.endswith('__init__.py')]
    # attribute-base names count as loads already
    if miss or unused: print(p,'MISSING',miss,'UNUSED',unused)
