import ast, os, inspect, sys, importlib
root='tally/reports'
mods={}
for dp,_,fs in os.walk(root):
    for f in fs:
        if f.endswith('.py'):
            p=os.path.join(dp,f); m=p[:-3].replace('/','.')
            if m.endswith('.__init__'): m=m[:-9]
            mods[m]=p

def layer(m):
    r=m[len('tally.reports'):].lstrip('.').split('.')[0]
    return {'':6,'errors':0,'tables':0,'state':0,'system':0,'formatting':1,'model':1,'loading':2,'aggregate':3,'renderers':4,'cli':5}[r]
edges={}
for m,p in mods.items():
    t=ast.parse(open(p).read()); pkg=m if p.endswith('__init__.py') else m.rsplit('.',1)[0]
    for n in ast.walk(t):
        tg=[]
        if isinstance(n,ast.Import): tg=[a.name for a in n.names]
        elif isinstance(n,ast.ImportFrom):
            base=n.module or ''
            if n.level:
                parts=pkg.split('.'); parts=parts[:len(parts)-(n.level-1)]
                base='.'.join(parts+([n.module] if n.module else []))
            for a in n.names:
                c=base+'.'+a.name
                tg.append(c if c in mods else base)
        for x in tg:
            if x.startswith('tally') and not x.startswith('tally.reports'): print('OUTSIDE',m,x)
            if x in mods:
                edges.setdefault(m,set()).add(x)
                if layer(x)>layer(m): print('LAYER',m,x)
            elif x.startswith('tally.reports'): print('??',m,x)
# cycles
state={}
def dfs(u,st):
    state[u]=1
    for v in edges.get(u,()):
        if state.get(v)==1: print('CYCLE',u,v)
        elif v not in state: dfs(v,st)
    state[u]=2
for m in mods: 
    if m not in state: dfs(m,[])
for m,p in mods.items():
    n=len(open(p).read().split('\n'))-1
    if n>400: print('BIG',p,n)
print('ok')
